<section class="hero" aria-label="<?= ($isDemo??true)?'Campañas de demostración':'Información destacada' ?>"><div class="swiper hero-swiper"><div class="swiper-wrapper"><?php foreach($slides as $index=>$slide):$image=$slide['image_url']??asset('images/'.$slide['image_desktop']);$mobile=$slide['image_url']??asset('images/'.$slide['image_mobile']);?><article class="swiper-slide hero-slide"><picture><source media="(max-width: 767px)" srcset="<?= e($mobile) ?>"><img class="hero-image" src="<?= e($image) ?>" alt="<?= e($slide['image_alt']??(($isDemo??true)?'Fotografía de referencia':'Imagen publicada de '.$slide['title'])) ?>" width="1600" height="1067" <?= $index===0?'fetchpriority="high"':'loading="lazy"' ?>></picture><div class="hero-shade"></div><div class="container hero-content"><p class="hero-eyebrow"><span></span><?= e($slide['eyebrow']) ?></p><?php if($index===0):?><h1 class="hero-title"><?= nl2br(e(str_replace('\n',"\n",$slide['title']))) ?></h1><?php else:?><h2 class="hero-title"><?= nl2br(e(str_replace('\n',"\n",$slide['title']))) ?></h2><?php endif?><p class="hero-description"><?= e($slide['subtitle']) ?></p><?php component('button',['href'=>$slide['href'],'label'=>$slide['button']]);?><?php if($isDemo??true):?><p class="hero-disclaimer">Campaña de demostración · Imagen de referencia</p><?php endif?></div></article><?php endforeach?></div></div><div class="container hero-bottom"><div class="hero-pagination"></div><div class="hero-controls"><span id="slide-number" aria-live="polite">01 / <?= e(str_pad((string)count($slides),2,'0',STR_PAD_LEFT)) ?></span><button id="hero-prev" aria-label="Anterior"><?= icon('arrow','rotate-180') ?></button><button id="hero-next" aria-label="Siguiente"><?= icon('arrow') ?></button></div></div></section>
